SELECT "t"."043d155b-b534-3526-a465-0caa72597d66" AS "bill_billing_period_start_date", "t"."3f450e09-7a9c-44d1-b04b-f73cd32a70d1.line_item_usage_account_id" AS "line_item_usage_account_id", "t"."3f450e09-7a9c-44d1-b04b-f73cd32a70d1.billing_entity" AS "billing_entity", "t"."3f450e09-7a9c-44d1-b04b-f73cd32a70d1.cost_center" AS "cost_center", "t"."3f450e09-7a9c-44d1-b04b-f73cd32a70d1.app_code" AS "app_code", "t"."3f450e09-7a9c-44d1-b04b-f73cd32a70d1.unblended_cost" AS "unblended_cost", "t"."3f450e09-7a9c-44d1-b04b-f73cd32a70d1.amortized_cost" AS "amortized_cost", "t"."3f450e09-7a9c-44d1-b04b-f73cd32a70d1.business_group" AS "business_group", "t"."3f450e09-7a9c-44d1-b04b-f73cd32a70d1.total_cost_exclude_master" AS "total_cost_exclude_master", "t"."3f450e09-7a9c-44d1-b04b-f73cd32a70d1.support_cost" AS "support_cost", "t0"."5ecf4946-c2b0-48cd-92cc-fe518a62f203.zesty_billing_date" AS "zesty_billing_date", "t0"."5ecf4946-c2b0-48cd-92cc-fe518a62f203.zesty_invoice" AS "zesty_invoice", "t0"."5ecf4946-c2b0-48cd-92cc-fe518a62f203.zesty_allocation_cost" AS "zesty_allocation_cost", "t1"."f64d3be1-cd27-4b0f-9af9-c869644336c4.account_id" AS "account_id", "t1"."f64d3be1-cd27-4b0f-9af9-c869644336c4.account_name" AS "account_name", "t1"."f64d3be1-cd27-4b0f-9af9-c869644336c4.account_group" AS "account_group", "t1"."f64d3be1-cd27-4b0f-9af9-c869644336c4.env" AS "env", "t1"."f64d3be1-cd27-4b0f-9af9-c869644336c4.budget" AS "budget", "t1"."f64d3be1-cd27-4b0f-9af9-c869644336c4.charge_type" AS "charge_type", "t1"."f64d3be1-cd27-4b0f-9af9-c869644336c4.cost_center_split" AS "cost_center_split", "t1"."f64d3be1-cd27-4b0f-9af9-c869644336c4.managed_by" AS "managed_by"
FROM (
SELECT "bill_billing_period_start_date" AS "043d155b-b534-3526-a465-0caa72597d66", "line_item_usage_account_id" AS "3f450e09-7a9c-44d1-b04b-f73cd32a70d1.line_item_usage_account_id", "billing_entity" AS "3f450e09-7a9c-44d1-b04b-f73cd32a70d1.billing_entity", "cost_center" AS "3f450e09-7a9c-44d1-b04b-f73cd32a70d1.cost_center", "app_code" AS "3f450e09-7a9c-44d1-b04b-f73cd32a70d1.app_code", "unblended_cost" AS "3f450e09-7a9c-44d1-b04b-f73cd32a70d1.unblended_cost", "amortized_cost" AS "3f450e09-7a9c-44d1-b04b-f73cd32a70d1.amortized_cost", "business_group" AS "3f450e09-7a9c-44d1-b04b-f73cd32a70d1.business_group", "total_cost_exclude_master" AS "3f450e09-7a9c-44d1-b04b-f73cd32a70d1.total_cost_exclude_master", "support_cost" AS "3f450e09-7a9c-44d1-b04b-f73cd32a70d1.support_cost"
FROM "PayerAwsDataCatalog"."athenacurcfn_greenfield_billing_report"."monthly_bill_by_account2_v6"
) AS "t"
LEFT JOIN (
SELECT "zesty_billing_date" AS "5ecf4946-c2b0-48cd-92cc-fe518a62f203.zesty_billing_date", "zesty_invoice" AS "5ecf4946-c2b0-48cd-92cc-fe518a62f203.zesty_invoice", "zesty_allocation_cost" AS "5ecf4946-c2b0-48cd-92cc-fe518a62f203.zesty_allocation_cost"
FROM "PayerAwsDataCatalog"."athenacurcfn_greenfield_billing_report"."monthly_bill_zesty_v2"
) AS "t0" ON "t"."043d155b-b534-3526-a465-0caa72597d66" = "t0"."5ecf4946-c2b0-48cd-92cc-fe518a62f203.zesty_billing_date"
LEFT JOIN (
SELECT "account_id" AS "f64d3be1-cd27-4b0f-9af9-c869644336c4.account_id", "account_name" AS "f64d3be1-cd27-4b0f-9af9-c869644336c4.account_name", "account_group" AS "f64d3be1-cd27-4b0f-9af9-c869644336c4.account_group", "env" AS "f64d3be1-cd27-4b0f-9af9-c869644336c4.env", "budget" AS "f64d3be1-cd27-4b0f-9af9-c869644336c4.budget", "charge_type" AS "f64d3be1-cd27-4b0f-9af9-c869644336c4.charge_type", "cost_center_split" AS "f64d3be1-cd27-4b0f-9af9-c869644336c4.cost_center_split", "managed_by" AS "f64d3be1-cd27-4b0f-9af9-c869644336c4.managed_by"
FROM "PayerAwsDataCatalog"."athenacurcfn_greenfield_billing_report"."account_map_v3"
) AS "t1" ON "t"."3f450e09-7a9c-44d1-b04b-f73cd32a70d1.line_item_usage_account_id" = "t1"."f64d3be1-cd27-4b0f-9af9-c869644336c4.account_id"
WHERE "t"."3f450e09-7a9c-44d1-b04b-f73cd32a70d1.billing_entity" = 'AWS'

